var getResults = function(queries) {
    let maxX = 50005;
    for (const q of queries) maxX = Math.max(maxX, q[1] + 1);
    const tree = new Int32Array(4 * (maxX + 1));
    function update(node, l, r, idx, val) {
        if (l === r) {
            tree[node] = val;
            return;
        }
        const mid = (l + r) >> 1;
        if (idx <= mid) update(node * 2, l, mid, idx, val);
        else update(node * 2 + 1, mid + 1, r, idx, val);
        tree[node] = Math.max(tree[node * 2], tree[node * 2 + 1]);
    }
    function query(node, l, r, ql, qr) {
        if (ql <= l && r <= qr) return tree[node];
        const mid = (l + r) >> 1;
        let res = 0;
        if (ql <= mid) res = Math.max(res, query(node * 2, l, mid, ql, qr));
        if (qr > mid) res = Math.max(res, query(node * 2 + 1, mid + 1, r, ql, qr));
        return res;
    }
    const obstacles = [0, maxX];
    update(1, 0, maxX, maxX, maxX);
    const ans = [];
    for (const q of queries) {
        if (q[0] === 1) {
            const x = q[1];
            let idx = 0;
            while (idx < obstacles.length && obstacles[idx] < x) idx++;
            const prevObs = obstacles[idx - 1];
            const nextObs = obstacles[idx];
            obstacles.splice(idx, 0, x);
            update(1, 0, maxX, x, x - prevObs);
            update(1, 0, maxX, nextObs, nextObs - x);
        } else {
            const x = q[1], sz = q[2];
            let idx = 0;
            while (idx < obstacles.length && obstacles[idx] <= x) idx++;
            const prevObs = obstacles[idx - 1];
            const maxPrevGap = query(1, 0, maxX, 0, prevObs);
            const tailGap = x - prevObs;
            ans.push(Math.max(maxPrevGap, tailGap) >= sz);
        }
    }
    return ans;
};
